#include <stdio.h>
#include <stdlib.h>
#include <string.h>

struct Packet {
    unsigned int len;
    unsigned char payload[];
};

int main(void) {
    unsigned int n = 5;
    struct Packet *p = malloc(sizeof *p + n);
    p->len = n;
    for (unsigned int i = 0; i < n; ++i) p->payload[i] = (unsigned char)(i * 10);
    printf("sizeof header = %zu (payload 不计入)\n", sizeof(struct Packet));
    printf("len=%u payload=", p->len);
    for (unsigned int i = 0; i < p->len; ++i) printf("%u ", p->payload[i]);
    printf("\n");
    free(p);
    return 0;
}
